tests.command:
cat > /tmp/frontier-hist-001-hist-001-run-001-09514a-qLiOUo/tests/issue-test.ts << 'EOF'
import { describe, test, expect } from "vitest";
import { cac } from "../src/index.ts";

describe("option default leak issue", () => {
  test("default should not leak to alias when long form parsed", () => {
    const cli = cac();
    cli.option("-b, --base-url <baseUrl>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "--base-url", "https://gitlab.com"]);
    expect(options.baseUrl).toBe("https://gitlab.com");
    expect(options.b).toBe("https://gitlab.com");
  });

  test("default should not leak to alias when short form parsed", () => {
    const cli = cac();
    cli.option("-b, --base-url <baseUrl>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "-b", "https://gitlab.com"]);
    expect(options.baseUrl).toBe("https://gitlab.com");
    expect(options.b).toBe("https://gitlab.com");
  });
});
EOF
